import re

def parse_input(text):
    """Extract JSON action from input text."""
    match = re.search(r'\{"action":\s*"([^"]+)"\s*(?:grid\h*=\h*([^\}}]+))?\s*\}', text.strip())
    if match:
        return match.group(1)
    return None

print(parse_input('{"action": "request_demos"}'))

